    bowl_patches = image_patch.find("bowl")
    salad_patches = image_patch.find("salad")
    pizza_patches = image_patch.find("pizza")

    if not bowl_patches or not salad_patches or not pizza_patches:
        return image_patch

    bowl_centers = [(p.left + p.right) / 2, (p.lower + p.upper) / 2 for p in bowl_patches]
    salad_centers = [(p.left + p.right) / 2, (p.lower + p.upper) / 2 for p in salad_patches]
    pizza_centers = [(p.left + p.right) / 2, (p.lower + p.upper) / 2 for p in pizza_patches]

    min_distance = float('inf')
    target_bowl = None

    for bowl_center in bowl_centers:
        for salad_center in salad_centers:
            for pizza_center in pizza_centers:
                dist = abs(bowl_center[0] - salad_center[0]) + abs(salad_center[0] - pizza_center[0])
                if dist < min_distance:
                    min_distance = dist
                    target_bowl = bowl_patches[bowl_centers.index(bowl_center)]

    return target_bowl

